/**
 * A server-owned side-effect template.
 */
export type OperatorSpec = OperatorSpecNotify | OperatorSpecHttp;

/**
 * Perform an HTTP request.
 */
export interface OperatorSpecHttp {
  /**
   * Credential authority; omitted for an unauthenticated request.
   */
  readonly auth?: HttpAuth | null;
  /**
   * Optional structured JSON body; string values are templates.
   */
  readonly body?: JsonValue;
  /**
   * Optional execution limits.
   */
  readonly budget?: OperatorBudget | null;
  /**
   * Optional human-readable purpose.
   */
  readonly description?: string | null;
  /**
   * Optional expected response status; any 2xx is accepted when omitted.
   */
  readonly expect_status?: number | null;
  /**
   * Optional request headers; values are templates.
   */
  readonly headers?: Readonly<Record<string, string>>;
  readonly kind: "http";
  /**
   * HTTP method.
   */
  readonly method: HttpMethod;
  /**
   * Optional request timeout, clipped to [`MAX_ATTEMPT_SECONDS`].
   */
  readonly timeout_seconds?: number | null;
  /**
   * URL template; its origin is literal and `{{field}}` placeholders may appear only in the path and query. A template beginning with `/` is path-only and is sent to the origin stored on the `auth` connection, read at each attempt; it requires `auth`.
   */
  readonly url: string;
}

