export type SourceCompletionOutcome = "complete" | "unavailable";

/**
 * Human-visible namespace for Cards and Runs.
 */
export type SpaceName = string;

/**
 * OTel-canonical span event.
 *
 * Fields:
 *
 * - `timestamp` — wall-clock time the event occurred. Must lie within the span's `[start_time, end_time]` window; that check is enforced by [`crate::vala::trace::SpanRecord::validate`], not here, because the event itself has no knowledge of its parent span. - `name` — event name. Free-form but non-empty; OTel conventions suggest namespaced names (`exception`, `log`, `gen_ai.evaluation.result`). - `attributes` — typed key/value bag stored as flat JSON. Use the constants in [`crate::vala::trace::attributes`] for known keys. - `dropped_attributes_count` — count of attributes the SDK dropped before sending (OTel default 0 means "none dropped"). Carried for parity with the OTLP proto.
 */
export interface SpanEvent {
  /**
   * Event attribute bag.
   */
  readonly attributes: Readonly<Record<string, JsonValue>>;
  /**
   * Count of attributes the SDK dropped before sending.
   */
  readonly dropped_attributes_count: number;
  /**
   * Event name; non-empty.
   */
  readonly name: string;
  /**
   * Wall-clock time the event occurred.
   */
  readonly timestamp: string;
}

export type SpanId = string;

/**
 * OTel canonical span kind. (Proto: `Span.SpanKind`.)
 */
export type SpanKind = "internal" | "server" | "client" | "producer" | "consumer";

/**
 * OTel-canonical span link.
 *
 * Fields:
 *
 * - `trace_id` / `span_id` — linked span identity. Both are typed (commit 02); the wire shape is hex strings. - `trace_state` — W3C TraceContext `tracestate` of the linked span (vendor list, comma-separated). Defaults to empty. - `flags` — full OTel proto `Link.flags` fixed32 bitfield. The low byte carries W3C trace flags (bit 0 = `sampled`); the upper bits are reserved by the OTel spec for SDK-internal signaling. Stored as `u32` so we don't truncate non-W3C bits at the contract layer. - `attributes` — typed key/value bag, same shape as [`super::SpanEvent::attributes`]. - `dropped_attributes_count` — count of attributes the SDK dropped before sending.
 */
export interface SpanLink {
  /**
   * Link attribute bag.
   */
  readonly attributes: Readonly<Record<string, JsonValue>>;
  /**
   * Count of attributes the SDK dropped before sending.
   */
  readonly dropped_attributes_count: number;
  /**
   * OTel proto `Link.flags` fixed32 bitfield. Bit 0 = `sampled`; upper bits reserved.
   */
  readonly flags: number;
  /**
   * Linked span id.
   */
  readonly span_id: SpanId;
  /**
   * Linked trace id.
   */
  readonly trace_id: TraceId;
  /**
   * W3C tracestate header value for the linked span.
   */
  readonly trace_state: string;
}

/**
 * One OTel-compliant span.
 */
export interface SpanRecord {
  /**
   * Span attribute bag. (Proto: `Span.attributes`.)
   */
  readonly attributes: Readonly<Record<string, JsonValue>>;
  /**
   * Count of span-level attributes the SDK dropped before sending.
   */
  readonly dropped_attributes_count: number;
  /**
   * Count of span events the SDK dropped before sending.
   */
  readonly dropped_events_count: number;
  /**
   * Count of span links the SDK dropped before sending.
   */
  readonly dropped_links_count: number;
  /**
   * Query convenience field equal to `(end_time - start_time)` in milliseconds.
   */
  readonly duration_ms: number;
  /**
   * Span end time. (Proto: `Span.end_time_unix_nano`.)
   */
  readonly end_time: string;
  /**
   * Span events. (Proto: `Span.events`.)
   */
  readonly events: readonly SpanEvent[];
  /**
   * OTel proto `Span.flags` fixed32 bitfield.
   */
  readonly flags: number;
  /**
   * Span kind. (Proto: `Span.kind`.)
   */
  readonly kind: SpanKind;
  /**
   * Span links. (Proto: `Span.links`.)
   */
  readonly links: readonly SpanLink[];
  /**
   * Span name. Non-empty and no longer than 256 bytes.
   */
  readonly name: string;
  /**
   * Parent span id. `None` for root spans.
   */
  readonly parent_span_id?: SpanId | null;
  /**
   * Resource of the producer.
   */
  readonly resource: Resource;
  /**
   * Instrumentation scope of the producer.
   */
  readonly scope: InstrumentationScope;
  /**
   * 8-byte span id. (Proto: `Span.span_id`.)
   */
  readonly span_id: SpanId;
  /**
   * Span start time. (Proto: `Span.start_time_unix_nano`.)
   */
  readonly start_time: string;
  /**
   * Span status. (Proto: `Span.status`.)
   */
  readonly status: SpanStatus;
  /**
   * 16-byte trace id. (Proto: `Span.trace_id`.)
   */
  readonly trace_id: TraceId;
  /**
   * W3C tracestate header. (Proto: `Span.trace_state`.)
   */
  readonly trace_state: string;
}

/**
 * OTel canonical span status. (Proto: `Span.Status`.)
 */
export type SpanStatus = SpanStatusUnset | SpanStatusOk | SpanStatusError;

/**
 * Operation failed with an optional human-readable description.
 */
export interface SpanStatusError {
  readonly code: "error";
  /**
   * Optional status description.
   */
  readonly description?: string | null;
}

/**
 * Operation completed successfully.
 */
export interface SpanStatusOk {
  readonly code: "ok";
}

/**
 * No status set; OTel default.
 */
export interface SpanStatusUnset {
  readonly code: "unset";
}

/**
 * DataCard split label.
 */
export type SplitName = string;

/**
 * Data split strategy.
 */
export type SplitStrategy = SplitStrategyMaterialized | SplitStrategyColumn | SplitStrategyIndexRange | SplitStrategyIndices;

/**
 * Predicate over a schema column.
 */
export interface SplitStrategyColumn {
  readonly kind: "Column";
  readonly value: SplitStrategyColumnValue;
}

export interface SplitStrategyColumnValue {
  /**
   * Schema column referenced by the predicate.
   */
  readonly name: ColumnName;
  /**
   * Predicate operator.
   */
  readonly op: Inequality;
  /**
   * Predicate comparison value.
   */
  readonly value: ColValue;
}

/**
 * Positional range using inclusive start and exclusive stop.
 */
export interface SplitStrategyIndexRange {
  readonly kind: "IndexRange";
  readonly value: SplitStrategyIndexRangeValue;
}

export interface SplitStrategyIndexRangeValue {
  /**
   * Inclusive starting index.
   */
  readonly start: number;
  /**
   * Exclusive stopping index.
   */
  readonly stop: number;
}

/**
 * Explicit positional indices.
 */
export interface SplitStrategyIndices {
  readonly kind: "Indices";
  readonly value: readonly number[];
}

/**
 * Reference to an already materialized split artifact.
 */
export interface SplitStrategyMaterialized {
  readonly kind: "Materialized";
  readonly value: Ref;
}

/**
 * SQL query bundle associated with SQL-backed DataCards.
 */
export interface SqlLogic {
  /**
   * Optional default query key.
   */
  readonly default_query?: QueryName | null;
  /**
   * Named SQL queries.
   */
  readonly queries: Readonly<Record<string, string>>;
}

/**
 * SQL interface metadata.
 */
export interface SqlMeta {
  /**
   * Optional connection hint for registry/runtime consumers.
   */
  readonly connection_hint?: string | null;
  /**
   * SQL dialect name.
   */
  readonly dialect: string;
}

/**
 * Server-derived Card status.
 */
export interface Status {
  /**
   * Human-readable status message.
   */
  readonly message?: string | null;
  /**
   * Lifecycle phase such as `draft`, `active`, or `deprecated`.
   */
  readonly phase: string;
  /**
   * Last status update timestamp.
   */
  readonly updated_at?: string | null;
  /**
   * Server-derived verification state, absent when the Card has none.
   *
   * Read-side projection only: it never changes the authored `spec`, and a registration request's own `status` is ignored.
   */
  readonly verification?: VerificationStatus | null;
}

/**
 * The execution record of one step.
 */
export interface StepResult {
  /**
   * Attempts made, retries included; zero when skipped.
   */
  readonly attempts: number;
  /**
   * Wall-clock duration across attempts.
   */
  readonly duration_ms: number;
  /**
   * Step ID.
   */
  readonly id: TaskId;
  /**
   * The action output, when capture permits it.
   */
  readonly output?: JsonValue;
  /**
   * What executed the action.
   */
  readonly provenance?: CallProvenance | null;
  /**
   * Why the step failed or was skipped.
   */
  readonly reason?: string | null;
  /**
   * Final status, as `steps.<id>.status` reads it.
   */
  readonly status: StepStatus;
  /**
   * Tools an Agent action called, in call order.
   */
  readonly tool_calls?: readonly ToolCallRecord[];
}

/**
 * Final status of one step.
 */
export type StepStatus = "succeeded" | "failed" | "skipped";

/**
 * Lifecycle status of a registered Bifrost table.
 */
export type TableStatus = "Active" | "Deprecated" | "Quarantined";

export type TaskId = string;

/**
 * Closed Wyrd ML task taxonomy.
 */
export type TaskType = "BinaryClassification" | "MultiClassClassification" | "Regression" | "Clustering" | "AnomalyDetection" | "Forecasting" | "Generation" | "Other";

/**
 * The body of a `task` Verifier: exactly one check, judged directly.
 *
 * A real-time assertion or LLM judge is not an Eval workflow, so it carries no task map, dataset, sampling, pass gate, or task graph. Its one `kind`-tagged definition sits directly under `implementation.spec` and reuses the existing assertion and LLM-judge payloads. Deserialization refuses `depends_on` and `condition`, which have no meaning for one check, and any unknown field such as a nested `task:` wrapper.
 */
export type TaskVerifierSpec = TaskVerifierSpecAssertion | TaskVerifierSpecLlmJudge;

/**
 * Programmatic assertion against the supplied context.
 */
export interface TaskVerifierSpecAssertion {
  /**
   * Optional gate evaluated before the task runs.
   */
  readonly condition?: EvalCondition | null;
  /**
   * Path to the single value to assert against.
   */
  readonly context_path?: JsonPath | null;
  /**
   * IDs of upstream tasks that must complete before this task runs.
   */
  readonly depends_on?: readonly TaskId[];
  /**
   * Right-hand side of the comparison.
   */
  readonly expected: JsonValue;
  /**
   * Unique identifier within the enclosing eval task map.
   */
  readonly id: TaskId;
  /**
   * Path to an array the runtime iterates and asserts per item.
   */
  readonly item_context_path?: JsonPath | null;
  readonly kind: "assertion";
  /**
   * Comparison applied to the observed value and expected value.
   */
  readonly operator: ComparisonOperator;
}

/**
 * LLM-as-judge evaluation of the supplied context.
 */
export interface TaskVerifierSpecLlmJudge {
  /**
   * Optional gate evaluated before the task runs.
   */
  readonly condition?: EvalCondition | null;
  /**
   * Optional JSONPath selecting the context passed to the judge.
   */
  readonly context_path?: JsonPath | null;
  /**
   * IDs of upstream tasks that must complete before this task runs.
   */
  readonly depends_on?: readonly TaskId[];
  /**
   * Right-hand side of the comparison.
   */
  readonly expected: JsonValue;
  /**
   * Unique identifier within the enclosing eval task map.
   */
  readonly id: TaskId;
  /**
   * Reference to or inline definition of an Agent card.
   */
  readonly judge_ref: InlineableRef_for_AgentSpec;
  readonly kind: "llm_judge";
  /**
   * Maximum retries on transient runtime failures.
   */
  readonly max_retries?: number;
  /**
   * Comparison applied to the judge response and expected value.
   */
  readonly operator: ComparisonOperator;
}

/**
 * Config for the Tensorflow model interface.
 */
export interface TensorflowMeta {
  /**
   * Installed tensorflow or keras version captured for reproducibility.
   */
  readonly framework_version: string;
  /**
   * Concrete model class name, when known.
   */
  readonly model_subtype?: string | null;
  /**
   * Save format for the tensorflow artifact.
   */
  readonly save_format: TfSaveFormat;
}

/**
 * Text manifest interface metadata.
 */
export interface TextMeta {
  /**
   * Text encoding used by local files.
   */
  readonly encoding?: string;
  /**
   * Optional manifest Artifact card reference.
   */
  readonly manifest_ref?: Ref | null;
}

/**
 * Save format for the Tensorflow model interface.
 */
export type TfSaveFormat = "Keras" | "SavedModel";

/**
 * Time-partition granularity on the wire.
 *
 * Bifrost partitions every table on its one time column and admits exactly these two Iceberg-native transforms; nothing else is representable.
 */
export type TimeGranularityWire = "hour" | "day";

/**
 * Timestamp / time precision. Arrow-free mirror of `arrow::datatypes::TimeUnit`.
 */
export type TimeUnit = "Second" | "Millisecond" | "Microsecond" | "Nanosecond";

/**
 * Audience (`aud`) of a Wyrd tenant access token.
 *
 * Every directly issued token is [`Self::Wyrd`] and is accepted on every tenant surface. A [`Self::Bifrost`] token is accepted only on the Bifrost surfaces, so a token delegated for Bifrost cannot be replayed elsewhere.
 */
export type TokenAudience = "wyrd" | "bifrost";

/**
 * One tool call an Agent action made.
 *
 * Records what the model received, never the raw tool output: the digest and size describe the bounded output actually returned. A call that returned no output, such as one that failed, has no digest and zero returned bytes rather than a digest of nothing.
 */
export interface ToolCallRecord {
  /**
   * Call arguments.
   */
  readonly arguments: JsonValue;
  /**
   * Error the tool returned, when it failed.
   */
  readonly error?: string | null;
  /**
   * SHA-256 of the bounded output returned to the model; absent when the call returned none.
   */
  readonly output_sha256?: Sha256Hex | null;
  /**
   * Bytes of output returned to the model; zero when it returned none.
   */
  readonly returned_bytes: number;
  /**
   * The built-in called.
   */
  readonly tool: BuiltinTool;
}

/**
 * Torch interface metadata.
 */
export interface TorchMeta {
  /**
   * Installed torch version inferred by the Python boundary.
   */
  readonly framework_version: string;
  /**
   * Torch serialization format.
   */
  readonly save_format: TorchSaveFormat;
}

/**
 * Config for the Torch model interface.
 */
export interface TorchMeta2 {
  /**
   * Installed torch version captured for reproducibility.
   */
  readonly framework_version: string;
  /**
   * Concrete module class name, when known.
   */
  readonly model_subtype?: string | null;
  /**
   * Save format for the torch artifact.
   */
  readonly save_format: TorchSaveFormat2;
}

/**
 * Torch serialization formats accepted by DataCard.
 */
export type TorchSaveFormat = "Safetensors" | "Pickle";

/**
 * Save format for the Torch model interface.
 */
export type TorchSaveFormat2 = "Safetensors" | "Pickle";

export type TraceId = string;

/**
 * Declarative activation for a bound Verifier.
 */
export type TriggerSpec = TriggerSpecSchedule | TriggerSpecObservationsReady;

/**
 * Activate on each successfully committed observation for the subject.
 *
 * Declared as a fieldless struct variant so the enum-level `deny_unknown_fields` applies: a unit variant's internally tagged visitor would silently drain every sibling key, admitting typos and pasted secrets. The authored wire shape stays `{kind: observations_ready}`.
 */
export interface TriggerSpecObservationsReady {
  /**
   * Optional human-readable purpose.
   */
  readonly description?: string | null;
  readonly kind: "observations_ready";
}

/**
 * Activate on each due occurrence of a cron schedule.
 */
export interface TriggerSpecSchedule {
  /**
   * Cron expression.
   */
  readonly cron: string;
  /**
   * Optional human-readable purpose.
   */
  readonly description?: string | null;
  readonly kind: "schedule";
  /**
   * Optional IANA timezone; absent means UTC.
   */
  readonly tz?: string | null;
}

/**
 * Card kinds whose `spec` and `status` `cards.get` types.
 */
export type TypedCardKind = "Data" | "Model" | "Prompt" | "Agent" | "Verifier" | "Service" | "Trigger" | "Operator";

/**
 * Admission of a call whose cost cannot be bounded.
 */
export type UnknownCostPolicy = "reject" | "allow_unpriced";

/**
 * `PATCH /v1/operator-connections/{connection_id}` body.
 *
 * Omitted fields are preserved; a supplied secret replaces the encrypted secret atomically. The provider tag must equal the stored provider, and the name is not patchable.
 */
export type UpdateOperatorConnectionRequest = UpdateOperatorConnectionRequestSlack | UpdateOperatorConnectionRequestPagerDuty | UpdateOperatorConnectionRequestHttp;

/**
 * Update an HTTP connection.
 */
export interface UpdateOperatorConnectionRequestHttp {
  /**
   * Replacement credential; may change its scheme and header name.
   */
  readonly auth?: HttpConnectionAuth | null;
  /**
   * Replacement origin.
   */
  readonly origin?: string | null;
  readonly provider: "http";
  /**
   * New status.
   */
  readonly status?: OperatorConnectionStatus | null;
}

/**
 * Update a PagerDuty connection.
 */
export interface UpdateOperatorConnectionRequestPagerDuty {
  /**
   * Replacement Global Integration key.
   */
  readonly integration_key?: SecretBearer | null;
  readonly provider: "pager_duty";
  /**
   * New status.
   */
  readonly status?: OperatorConnectionStatus | null;
}

/**
 * Update a Slack connection.
 */
export interface UpdateOperatorConnectionRequestSlack {
  /**
   * Replacement bot token.
   */
  readonly bot_token?: SecretBearer | null;
  readonly provider: "slack";
  /**
   * New status.
   */
  readonly status?: OperatorConnectionStatus | null;
  /**
   * Replacement workspace ID.
   */
  readonly workspace_id?: string | null;
}

/**
 * One inline declaration attaching a Verifier to its containing subject.
 *
 * Authored on a Service, a Service component occurrence, or a standalone Agent. Registration resolves and UID-pins the Verifier, the effective Trigger, and every effective Operator before the owning Card persists.
 */
export interface VerificationBinding {
  /**
   * Operators dispatched independently after a `failed` verdict.
   *
   * Empty means a failed result stays durable with no reaction.
   */
  readonly on_failure?: readonly InlineableRef_for_OperatorSpec[];
  /**
   * When the bound Verifier runs, inline or as a referenced Trigger Card.
   *
   * Absent means explicit-only: the binding attaches the Verifier to its subject for direct invocation and nothing activates it.
   */
  readonly runs_on?: InlineableRef_for_TriggerSpec | null;
  /**
   * The exact Verifier Card this subject is verified by.
   */
  readonly verifier: Ref;
}

/**
 * Structured, secret-free execution or delivery error.
 */
export interface VerificationError {
  /**
   * Stable machine-readable error code.
   */
  readonly code: string;
  /**
   * Bounded human-readable description.
   */
  readonly message: string;
}

/**
 * `GET /v1/verification/executions/{execution_id}` response.
 *
 * A conflicting idempotent replay settles as `errored` with the idempotency-conflict code and never carries a result. `completed` may briefly lack a visible result.
 */
export interface VerificationExecutionState {
  /**
   * Terminal error of an `errored`, `cancelled`, or `timed_out` execution.
   */
  readonly error?: VerificationError | null;
  /**
   * The execution.
   */
  readonly execution_id: string;
  /**
   * The result once completed and visible.
   */
  readonly result?: VerificationResult | null;
  /**
   * Lifecycle status, independent of the verdict.
   */
  readonly status: VerificationExecutionStatus;
}

/**
 * Execution state of one Verifier run.
 *
 * Independent of the verdict: only `completed` has one, and it lives in the Bifrost result the run points at. `cancelled`, `timed_out`, and `errored` never carry a verdict or dispatch an Operator.
 */
export type VerificationExecutionStatus = "pending" | "running" | "retrying" | "completed" | "cancelled" | "timed_out" | "errored";

/**
 * Overall verdict with its requirement and step breakdown.
 */
export interface VerificationOutcome {
  /**
   * The pinned original evidence, by slot.
   */
  readonly evidence: Readonly<Record<string, InputDeclaration>>;
  /**
   * Every requirement, step requirements included.
   */
  readonly requirements: readonly RequirementResult[];
  /**
   * Every step in plan order.
   */
  readonly steps: readonly StepResult[];
  /**
   * The `decide` rule applied to every applicable requirement.
   */
  readonly verdict: VerificationVerdict;
}

/**
 * The attributable result of one Verifier execution.
 */
export interface VerificationResult {
  /**
   * Server-issued execution identity.
   */
  readonly execution_id: string;
  /**
   * Verdict, breakdown, and evidence.
   */
  readonly outcome: VerificationOutcome;
  /**
   * The caller's application Run, when there is one.
   */
  readonly run_id?: string | null;
  /**
   * The exact subject judged.
   */
  readonly subject: CardRef;
  /**
   * The exact Verifier executed.
   */
  readonly verifier: CardRef;
}

/**
 * Server-derived verification state projected onto `card.status`.
 *
 * A Service or standalone Agent owning `verified_by` bindings exposes the stable identity of each projected binding here, so a caller can address a binding without a separate listing resource. The field is read-only: it is derived from the tenant's binding projection on every Card read and is never persisted as Card status.
 */
export interface VerificationStatus {
  /**
   * Fitted-baseline readiness of a PSI or SPC Drift Verifier Card version.
   *
   * Absent on every other Card, including a Custom Drift Verifier, which scores its authored scalar baseline and is ready without fitting.
   */
  readonly baseline?: DriftBaselineStatus | null;
  /**
   * Stable identities of this owner Card version's projected bindings, ordered by identity so reordering authored bindings changes nothing.
   */
  readonly binding_ids?: readonly string[];
}

/**
 * Common Verifier verdict of a completed run.
 *
 * Carried by the Bifrost result and used by settlement to decide Operator dispatch; Run GET never returns it.
 */
export type VerificationVerdict = "passed" | "failed" | "inconclusive";

/**
 * The closed set of Verifier implementations.
 *
 * Adjacently tagged so that `implementation.kind` selects the variant and the variant's own typed body lives under `implementation.spec`. An unknown `kind` fails deserialization before validation or persistence, so a future implementation cannot be authored until its variant ships.
 */
export type VerifierImplementation = VerifierImplementationDrift | VerifierImplementationEval | VerifierImplementationTask;

/**
 * Continuous distribution or metric drift over observed records.
 */
export interface VerifierImplementationDrift {
  readonly kind: "drift";
  readonly spec: DriftSpec;
}

/**
 * Task-based evaluation over committed observations.
 */
export interface VerifierImplementationEval {
  readonly kind: "eval";
  readonly spec: EvalSpec;
}

/**
 * One direct assertion or LLM judge over supplied JSON context.
 */
export interface VerifierImplementationTask {
  readonly kind: "task";
  readonly spec: TaskVerifierSpec;
}

/**
 * Verifier Card spec body.
 *
 * One Verifier declares one implementation. Independent judgments are composed by attaching multiple Verifier Cards, never by nesting implementations or introducing a Verifier DAG.
 */
export interface VerifierSpec {
  /**
   * Optional human-readable purpose.
   */
  readonly description?: string | null;
  /**
   * The single typed implementation this Verifier runs.
   */
  readonly implementation: VerifierImplementation;
}

/**
 * Semver-compatible version string.
 */
export type VersionBlock = string;

/**
 * Semantic version bump level.
 *
 * `Major`, `Minor`, and `Patch` perform a conventional semver bump and clear any pre-release / build metadata. `Pre`, `Build`, and `PreBuild` are additive: they apply the requested pre-release or build metadata to the existing triple without resetting it.
 */
export type VersionBump = "major" | "minor" | "patch" | VersionBumpPre | VersionBumpBuild | VersionBumpPreBuild;

/**
 * Set the build metadata on the current triple (e.g. "001", "sha-abc123").
 */
export interface VersionBumpBuild {
  readonly build: VersionBumpBuildBuild;
}

export interface VersionBumpBuildBuild {
  /**
   * Build metadata as defined by SemVer 2.0 §10.
   */
  readonly metadata: string;
}

/**
 * Set the pre-release identifier on the current triple (e.g. "rc.1").
 */
export interface VersionBumpPre {
  readonly pre: VersionBumpPrePre;
}

/**
 * Set both pre-release and build metadata on the current triple.
 */
export interface VersionBumpPreBuild {
  readonly pre_build: VersionBumpPreBuildPreBuild;
}

export interface VersionBumpPreBuildPreBuild {
  /**
   * Build metadata.
   */
  readonly build: string;
  /**
   * Pre-release identifier.
   */
  readonly pre: string;
}

export interface VersionBumpPrePre {
  /**
   * Pre-release identifier as defined by SemVer 2.0 §9.
   */
  readonly identifier: string;
}

/**
 * Authored version on the card-registration path. Either a full semver triple pin (e.g. "1.4.2", "1.4.2-rc.1+meta") or a bare partial scope (e.g. "1", "1.0"). Range comparators (^, ~, *, >=, ...) are rejected on this path.
 */
export type VersionSpec = string;

/**
 * Author-declared workflow field map for eval task inputs and outputs.
 */
export interface Workflow {
  /**
   * Map from workflow field name to the expected JSON shape at that key.
   */
  readonly fields: Readonly<Record<string, WorkflowFieldType>>;
}

/**
 * Declared JSON shape for one workflow field.
 */
export type WorkflowFieldType = "string" | "integer" | "float" | "boolean" | "object" | "array" | "any";

/**
 * RFC 9457 problem value emitted by every public Wyrd error boundary.
 */
export interface WyrdProblem {
  /**
   * Stable Wyrd error code.
   */
  readonly code: string;
  /**
   * Human-readable problem detail.
   */
  readonly detail: string;
  /**
   * Structured machine-readable details.
   */
  readonly details: JsonValue;
  /**
   * Remediation guidance.
   */
  readonly remediation: string;
  /**
   * HTTP status.
   */
  readonly status: number;
  /**
   * Short problem title.
   */
  readonly title: string;
  /**
   * Problem type URI.
   */
  readonly type: string;
}

/**
 * Config for the Xgboost model interface.
 */
export interface XgboostMeta {
  /**
   * Installed xgboost version captured for reproducibility.
   */
  readonly framework_version: string;
  /**
   * Concrete model subtype, when known.
   */
  readonly model_subtype?: string | null;
}
